import numpy as np
from numba import njit

@njit(cache=True)
def auction(cost):
    n = cost.shape[0]
    a = -cost
    prices = np.zeros(n)
    assign = np.full(n, -1, dtype=np.int64)
    maxv = a.max()
    minv = a.min()
    eps = (maxv - minv) / 2.0
    if eps <= 0:
        eps = 1.0
    while eps > 1.0 / (n + 1):
        for i in range(n):
            best_j = -1
            best_v = -1e300
            second_v = -1e300
            for j in range(n):
                v = a[i, j] - prices[j]
                if v > best_v:
                    second_v = best_v
                    best_v = v
                    best_j = j
                elif v > second_v:
                    second_v = v
            if best_j < 0:
                continue
            bid = best_v - second_v + eps
            prices[best_j] += bid
            prev = assign[best_j]
            assign[best_j] = i
        eps *= 0.25
    result = np.full(n, -1, dtype=np.int64)
    for j in range(n):
        if assign[j] >= 0:
            result[assign[j]] = j
    for i in range(n):
        if result[i] < 0:
            best_j = -1
            best_v = 1e300
            for j in range(n):
                if assign[j] < 0:
                    v = cost[i, j]
                    if v < best_v:
                        best_v = v
                        best_j = j
            result[i] = best_j
            assign[best_j] = i
    return result

